def _member_id(member: dict) -> str:
    mid = member.get("id")
    if not isinstance(mid, str) or len(mid) == 0:
        return ""
    return mid


def _validate_tier(member: dict) -> str | None:
    if member["tier"] not in TIER_FEES:
        return "unknown tier"
    return None


def _validate_payment(payment: dict) -> str | None:
    amount = payment.get("amount")
    if not isinstance(amount, int) or amount <= 0:
        return "bad amount"
    if payment.get("method") not in ("card", "transfer"):
        return "unsupported method"
    return None


