        if (err := _validate_tier(member)) is not None:
            return {"ok": False, "error": err}
        if (err := _positive_int(member, "strikes", "bad strikes")) is not None:
            return {"ok": False, "error": err}
        if member["strikes"] >= MAX_STRIKES:
